<?php
namespace App\Foundation\Console;use App\Foundation\Design\DesignInspector;use App\Foundation\Generation\FilePlan;use App\Foundation\Registry\ProjectRegistry;
final class DesignRemoveCommand extends FoundationCommand{protected $signature='design:remove {name} {--dry-run} {--force}';protected $description='Remove a design manifest after usage checks.';public function handle(FilePlan $p,ProjectRegistry $r,DesignInspector $i):int{$name=$this->argument('name');$uses=$i->usage($name);if($uses&&!$this->option('force')){$this->error('Used by: '.implode(', ',$uses));return self::FAILURE;}foreach($r->design() as $d){if(strcasecmp($d['name'],$name)===0){$p->delete(str_replace(base_path().'/','',$d['_file']));return $this->runPlan($p,"design:remove {$name}");}}$this->error('Not found.');return self::FAILURE;}}
